  "assertions": [
    {
      "claim_text": "EBL net profit up 32% this quarter, best in the sector.",
      "status": "contradicted",
      "source_figure": "EBL annual net profit growth was 30.7%; sector combined profit grew 32.33% led by Nabil Bank",
      "quote": "That figure belongs to the sector, not to EBL, and covers a different period from EBL's 2081/82 annual results. EBL's own annual growth was 30.7%.",
      "source_file": "sources/ebl.md"
    },
    {
      "claim_text": "Still trading below book value",
      "status": "contradicted",
      "source_figure": "2.96x book value",
      "quote": "Price to book: 729.50 / 246.74 = 2.96x — trading at nearly three times book value",
      "source_file": "sources/ebl.md"
    }
  ],
  "computed": {
    "price_to_book": "729.50 / 246.74 = 2.96x"
  },
  "summary": "The claim misattributes sector-wide figures to Everest Bank Limited, as the 32.33% growth figure refers to total commercial bank sector profit led by Nabil Bank, whereas EBL's annual net profit growth was 30.7%. Additionally, EBL is not trading below book value; with a stock price of Rs 729.50 and net worth per share of Rs 246.74, it trades at nearly three times book value (2.96x)."
}

